<?php require_once __DIR__.'/../includes/functions.php';require_role('student');$s=$pdo->prepare("SELECT r.obtained_marks,r.total_marks,r.percentage,r.grade,r.result_status FROM results r JOIN students st ON st.id=r.student_id WHERE st.user_id=? AND r.published=1");$s->execute([$_SESSION['user']['id']]);$rows=$s->fetchAll();$pageTitle='Results';$base='../';require __DIR__.'/../includes/header.php';?>
<div class="layout"><?php require __DIR__.'/../includes/sidebar.php';?><section class="content"><div class="card"><h1>Results</h1><div class="table-wrap"><table class="table"><?php if($rows):?><tr><?php foreach(array_keys($rows[0]) as $h):?><th><?=e(ucwords(str_replace('_',' ',$h)))?></th><?php endforeach;?></tr><?php foreach($rows as $r):?><tr><?php foreach($r as $v):?><td><?=e((string)$v)?></td><?php endforeach;?></tr><?php endforeach;?><?php endif;?></table></div></div></section></div><?php require __DIR__.'/../includes/footer.php';?>